def write_trace_annex(w,app,table):
 app('Ж','Сквозное обеспечение операций процессов',first=True)
 para(w,'Для каждого листа дерева определена операция процесса и требуемое программное средство. Код ОП обозначает операцию, а не готовый модуль. Компоненты объединяют повторяющиеся средства; задания М01–М11 в приложении Д раскрывают их реализацию. На диаграммах В.2–В.6 показаны основные операции; простое ведение справочников и закрытие договора раскрыты дополнительно на В.8 и В.9.')
 for start in range(0,len(OPERATIONS),5):
  rows=[(f,o,s+'; '+k,m+'\n'+handler+'\n'+tests) for f,o,s,k,m,handler,tests in OPERATIONS[start:start+5]]
  table(w,'Операции и средства исполнения часть '+str(start//5+1),['Лист','Операция / процесс','Необходимое средство / компонент','Реализация / проверка'],rows,[17,28,62,58])
